  const evaluationSha = validateCommitSha(evaluationCommitSha);
  const absoluteInstance = resolveRepoFile(instanceRelativePath);
  if (!fs.existsSync(absoluteInstance)) throw new Error(`Task instance not found: ${instanceRelativePath}`);

  const instance = readJson(absoluteInstance);
  const target = instance?.verify_target_array?.filename;
  const predicates = filePredicates(target);
  const ready = predicates.file_does_exist_$bool && predicates.file_is_json_$bool && predicates.file_is_minified_$bool && predicates.file_is_flattened_$bool;
  let pass = ready;
  let expectedSignatures = null;
  let expectedCount = null;
  let archiveFilename = null;
  let failure = null;

  try {
    if (!ready) throw new Error('Target-array readiness truth table did not evaluate to AND=true.');
    expectedSignatures = expectedNonemptySignatures(predicates.parsed);
    expectedCount = expectedSignatures.length;

    if (JSON.stringify(instance?.doRecord_withReturnSchema?.semantic_evaluations) !== JSON.stringify(EXPECTED_EVALS)) {
      throw new Error('semantic_evaluations does not match the required evaluation contract.');
    }
    if (instance?.count_array_nonempty_items?.filename !== '$verify_target_array.filename') throw new Error('count_array_nonempty_items.filename no longer points to verify_target_array.filename.');
    if (instance?.count_array_nonempty_items?.how_many !== expectedCount) throw new Error(`how_many must equal ${expectedCount}.`);
    if (instance?.doRecord_withReturnSchema?.original_array_filename !== '$verify_target_array.filename') throw new Error('original_array_filename no longer points to verify_target_array.filename.');
    if (instance?.doRecord_withReturnSchema?.nonempty_items_counted !== expectedCount) throw new Error(`nonempty_items_counted must equal ${expectedCount}.`);
    if (instance?.doRecord_withReturnSchema?.returnSchemaArraySize !== expectedCount) throw new Error(`returnSchemaArraySize must equal ${expectedCount}.`);

    const batches = instance?.doRecord_withReturnSchema?.batch_archive_filenames;
    if (!Array.isArray(batches) || (expectedCount > 0 && batches.length === 0)) throw new Error('batch_archive_filenames must record the generated batch archives.');

    archiveFilename = instance?.combine_and_send_batch_archives?.complete_batch_archive_filename;
    if (typeof archiveFilename !== 'string' || archiveFilename.trim() === '' || archiveFilename === 'not_yet_combined') throw new Error('complete_batch_archive_filename has not been completed.');

    const records = parseJsonArchive(archiveFilename);
    if (!validateSemanticEvaluationArray(records, expectedSignatures)) {
      throw new Error('Complete archive does not contain exactly one literal-signature keyed record with all six required semantic evaluations, in source order, for every non-empty source signature.');
    }
  } catch (error) {
    pass = false;
    failure = error.message;
  }

  fs.rmSync(absoluteInstance, { force: true });

  if (pass) {
    writeJson(resultPathFor(evaluationSha, 'PASS'), {
      status: 'PASS',
      task: TASK_ID,
      source_filename: target,
      nonempty_items_counted: expectedCount,
      semantic_evaluations: EXPECTED_EVALS,
      complete_batch_archive_filename: archiveFilename
    });
    console.log(`[comprehension-task] PASS ${evaluationSha}`);
    return true;
  }

  writeJson(resultPathFor(evaluationSha, 'FAILED'), {
    status: 'FAILED',
    task: TASK_ID,
    reason: failure || 'Task completion verification failed.'
  });
  console.log(`[comprehension-task] FAILED ${evaluationSha}: ${failure || 'verification failed'}`);
  return false;
}"}

{"i":30,"id":"StateMachines:ChatMachines/GeminiEvaluation/evaluations/live_ground_truth_implementation_revision_20261002_1/outputs/revised-send-to-gemini.js:15415-18370","source":"function initRun(runNonce, steps) {
  const dir = path.join(supervisorConfig.runsRoot, runNonce);
  const stateFile = path.join(dir, 'state.json');
  const messagesFile = path.join(dir, 'messages.json');
  const storeFile = path.join(dir, 'store', 'store.json');
  const ledgerFile = path.join(dir, supervisorConfig.observationLedgerFilename);
  const exists = [stateFile, messagesFile, storeFile].some(fs.existsSync);
  let wrapper, messages, store;

  if (!exists) {
    wrapper = {
      current_state: {
        run_nonce: runNonce,
        status: 'awaiting_chatgpt_execution',
        created_at: now(),
        updated_at: now(),
        event_count: 0,
        procedure: {
          current_step: steps[0],
          completed_steps: [],
          remaining_steps: [...steps],
          step_records: {},
          awaiting: { type: 'chatgpt_execution', step: steps[0] }
        }
      }
    };
    messages = { run_nonce: runNonce, contents: [] };
    store = { run_nonce: runNonce, created_at: now(), initial_user_message: null, records: [] };
    writeJson(stateFile, wrapper);
    writeJson(messagesFile, messages);
    writeJson(storeFile, store);
  } else {
    if (![stateFile, messagesFile, storeFile].every(fs.existsSync)) {
      throw new Error(`Incomplete run container ${dir}`);
    }
    wrapper = readJson(stateFile);
    messages = readJson(messagesFile);
    store = readJson(storeFile);
    for (const [label, value] of [
      ['state', wrapper.current_state?.run_nonce],
      ['messages', messages.run_nonce],
      ['store', store.run_nonce]
    ]) {
      if (value !== runNonce) throw new Error(`Mismatched run_nonce in ${label}`);
    }
    const state = wrapper.current_state;
    state.procedure = state.procedure || {};
    state.procedure.completed_steps = Array.isArray(state.procedure.completed_steps)
      ? state.procedure.completed_steps : [];
    state.procedure.step_records = state.procedure.step_records || {};
    state.event_count = Number.isInteger(state.event_count) ? state.event_count : 0;
    state.procedure.remaining_steps = steps.filter(s => !state.procedure.completed_steps.includes(s));
    if (state.procedure.current_step !== null && !steps.includes(state.procedure.current_step)) {
      state.procedure.current_step = state.procedure.remaining_steps[0] ?? null;
    }
    if (state.procedure.current_step === null && state.procedure.remaining_steps.length) {
      state.procedure.current_step = state.procedure.remaining_steps[0];
    }
    state.procedure.awaiting = state.procedure.current_step === null
      ? null : { type: 'chatgpt_execution', step: state.procedure.current_step };
  }

  const ledger = new ObservationLedger(ledgerFile, runNonce);
  const gateway = new EvidenceGateway(ledger);

  return {
    dir,
    stateFile,
    messagesFile,
    storeFile,
    ledgerFile,
    ledger,
    gateway,
    wrapper,
    state: wrapper.current_state,
    messages,
    store
  };
}"}

{"i":31,"id":"StateMachines:ChatMachines/GeminiEvaluation/evaluations/live_ground_truth_implementation_revision_20261002_1/outputs/revised-send-to-gemini.js:2724-3121","source":"function stepsFrom(agents) {
  const out = [];
  const seen = new Set();
  const re = /^## Step\s+(\d+)\s*$/gm;
  let match;
  while ((match = re.exec(agents))) {
    const step = Number(match[1]);
    if (!seen.has(step)) {
      seen.add(step);
      out.push(step);
    }
  }
  if (!out.length) throw new Error('Agents.md contains no ## Step N headings.');
  return out.sort((a, b) => a - b);
}"}

