{"i":33,"id":"StateMachines:ChatMachines/GeminiEvaluation/evaluations/live_ground_truth_implementation_revision_20261002_1/outputs/revised-send-to-gemini.js:51876-53653","source":"function runObservationMode({ runNonce, requestFile, receiptOutputFile }) {
  const steps = [0, 1, 2, 3, 4];
  const run = initRun(runNonce, steps);
  const gateway = run.gateway;
  const ledger = run.ledger;

  let requests = [];
  if (requestFile && fs.existsSync(requestFile)) {
    const parsed = readJson(requestFile);
    requests = Array.isArray(parsed) ? parsed : parsed.requests || [];
  }

  const receipts = [];
  for (const req of requests) {
    const { target, operation = 'read_file', claimed_content = null, material = true } = req;
    let obs;
    if (operation === 'git_head') {
      obs = gateway.observeGitHead(material);
    } else if (operation.startsWith('git_')) {
      const kind = operation === 'git_commit' ? 'commit' : 'blob';
      obs = gateway.observeGitObject(target, kind, material);
    } else {
      obs = gateway.observeFile(target, claimed_content, material);
    }
    receipts.push({
      request_id: req.request_id || `req_${receipts.length + 1}`,
      observation_id: obs.obs_id,
      sequence: obs.sequence,
      operation: obs.operation,
      target: obs.target,
      version_ref: obs.version_ref,
      content_hash: obs.content_hash,
      status: obs.status,
      excerpt: obs.excerpt,
      parent_hash: obs.parent_hash,
      record_hash: obs.record_hash,
      timestamp: obs.timestamp
    });
  }

  const outputTarget = receiptOutputFile || path.join(run.dir, supervisorConfig.observationReceiptsFilename);
  writeJson(outputTarget, {
    run_nonce: runNonce,
    generated_at: now(),
    total_receipts: receipts.length,
    receipts
  });

  console.log(JSON.stringify({
    mode: 'observation_receipt',
    run_nonce: runNonce,
    receipt_count: receipts.length,
    receipt_file: outputTarget
  }, null, 2));
}"}

{"i":34,"id":"StateMachines:ChatMachines/GeminiEvaluation/hierarchical-runtime/audit.js:22990-24024","source":"async function executeRetryConditionals({initialAttempt, B, b, batch, evaluator, iterator, config, gemini, dependencies}) {
  const conditionals = iterator.retry?.conditionals || [];
  let current = initialAttempt;
  let retryNumber = 0;
  for (const conditional of conditionals) {
    if (!retryConditionalMatches({conditional, attempt: current, retryNumber})) continue;
    const retryInput = buildRetryInput({inputs: conditional.invoke?.inputs || [], B, b, batch, evaluator, attempt: current, retryNumber});
    const retried = await executeEvaluatorAttempt({B, b, batch, evaluator, iterator, retryInput, config, gemini, dependencies});
    retryNumber += 1;
    retried.retryCount = retryNumber;
    if (retried.accepted) return applyRetrySuccess({conditional, attempt: retried});
    current = retried;
    current.retryCount = retryNumber;
    if (conditional.on_failure?.stop_retry_sequence === true) return applyRetryFailureTerminal({conditional, attempt: current});
  }
  current.retryCount = retryNumber;
  return current;
}"}

{"i":35,"id":"StateMachines:ChatMachines/GeminiEvaluation/hierarchical-runtime/audit.js:24327-25118","source":"function buildRetryInput({inputs, B, b, batch, evaluator, attempt, retryNumber}) {
  const available = {
    context: batch.context,
    previous_response: attempt.normalizedResponse ?? attempt.rawResponse,
    mechanical_error: attempt.mechanicalError,
    task: evaluator.task,
    criteria: evaluator.criteria,
    response_contract: evaluator.response_contract,
    original_invocation: {context: batch.context, task: evaluator.task, criteria: evaluator.criteria, response_contract: evaluator.response_contract},
    attempt_number: retryNumber,
    B,
    b
  };
  const result = {};
  for (const name of inputs) {
    if (!Object.prototype.hasOwnProperty.call(available, name)) throw new Error(`Unknown retry input: ${name}`);
    result[name] = available[name];
  }
  return result;
}"}

{"i":36,"id":"StateMachines:ChatMachines/GeminiEvaluation/hierarchical-runtime/audit.js:3494-4298","source":"async function countTokens({value, config, dependencies, gemini}) {
  if (typeof dependencies?.countTokens === 'function') {
    return dependencies.countTokens(value, config);
  }
  if (typeof gemini?.countTokens === 'function') {
    try {
      const res = await gemini.countTokens({contents: value});
      if (typeof res?.totalTokens === 'number') return res.totalTokens;
      if (typeof res === 'number') return res;
    } catch {}
  }

  let text = '';
  if (typeof value === 'string') {
    text = value;
  } else if (value !== null && value !== undefined) {
    try {
      text = JSON.stringify(value);
    } catch {
      text = String(value);
    }
  }
  if (!text) return 0;
  const matches = text.match(/\w+|[^\s\w]|\s+/g);
  return matches ? matches.length : Math.ceil(text.length / 4);
}"}

